import{z as o,x as A,o as B,c as p,q as r,j as l,D as e,d as n,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"主权财富基金","description":"","frontmatter":{"title":"主权财富基金","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sovereign-wealth-funds.md","filePath":"econ/sovereign-wealth-funds.md","lastUpdated":1791413859000}'),d={name:"econ/sovereign-wealth-funds.md"};function F(S,a,m,u,D,c){const t=A("Mermaid");return B(),p("div",null,[a[2]||(a[2]=r('<h1 id="主权财富基金" tabindex="-1">主权财富基金 <a class="header-anchor" href="#主权财富基金" aria-label="Permalink to &quot;主权财富基金&quot;">​</a></h1><div class="epigraph"><p>把不可再生收入或外汇顺差从短期储备换成跨期资产组合，是官方的永久收入；治理与稳定目标决定它是储蓄还是另一只干预的手。</p><footer>—— 据 Truman 主权财富基金记分；Aizenman 储备与 SWF；对照永久收入与资源诅咒讨论</footer></div><p><a href="/econ/capital-controls">上一课</a>写资本流的闸。本课换官方资产：主权财富基金（SWF）。欧元区危机下一课换一种货币下的主权债。本课钉 SWF 与储备的分工，接到<a href="/econ/permanent-income">永久收入</a>与全球失衡，不写某只基金的持仓清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>储备：流动性、干预、自我保险，资产短、安全、美元。SWF：来自资源租金或持续顺差，目标是跨代平滑、或降低持有储备的准财政成本。永久收入：资源是财富一次总付，应把大部分投资到海外金融，国内吸收平滑——否则 \\(G\\) 与实际汇率荷兰病。缺口不是再讲怕浮动，而是：同一官方外汇，保险库存与储蓄组合要分账，否则干预会掏空储蓄，或储蓄目标会绑死汇率政策。</p><p><span class="marginnote">术语翻译：「荷兰病」得名于荷兰发现天然气后——外汇大量涌入推高本币与国内物价，出口制造业反被挤垮。钱变多了，病的是实体部门；SWF 的一个核心任务就是把这笔冲击拦在海外资产里。</span></p><p><span class="marginnote">Santiago 原则是治理自愿准则。透明度、与央行分家、国内产业政策禁区，决定 SWF 是宏观工具还是政治钱包。Truman 记分卡量的是这个，不是 α。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分账：央行储备 vs 财政部 / 独立 SWF。负债侧：无明确负债（资源）vs 有 implicit 养老金。资产侧：从国债向股票、公司债、另类——风险与政治敏感上升（投资审查）。与失衡：石油与东亚 SWF 是上流的官方腿之一，比干预储备期限更长。计量不在本课估 SWF 对东道国股价的平均效应。</p>',9)),(B(),l(i,null,{default:e(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RENT%5B%22%E8%B5%84%E6%BA%90%20%2F%20%E9%A1%BA%E5%B7%AE%22%5D%20--%3E%20SPLIT%5B%22%E5%88%86%E8%B4%A6%22%5D%0A%20%20SPLIT%20--%3E%20RES%5B%22%E5%82%A8%E5%A4%87%3A%20%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BF%9D%E9%99%A9%22%5D%0A%20%20SPLIT%20--%3E%20SWF%5B%22SWF%3A%20%E8%B7%A8%E6%9C%9F%E5%82%A8%E8%93%84%22%5D%0A%20%20PIH%5B%22%E6%B0%B8%E4%B9%85%E6%94%B6%E5%85%A5%22%5D%20--%3E%20SMOOTH%5B%22%E5%9B%BD%E5%86%85%E5%90%B8%E6%94%B6%E5%B9%B3%E6%BB%91%22%5D%0A%20%20GOV%5B%22%E6%B2%BB%E7%90%86%E5%B7%AE%22%5D%20--%3E%20POL%5B%22%E4%BA%A7%E4%B8%9A%E6%94%BF%E7%AD%96%20%2F%20%E6%8E%8F%E7%A9%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 Lucas：官方可以买富国资产（上流），私人 \\(MPK\\) 仍可不南流。SWF 不解决穷国制度，只是资源国自己的组合。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是跨期与代理。资源价格冲击若全部进国内 \\(G\\)，实际汇率升、可贸易部门伤（荷兰病）。SWF 把冲击拦在海外资产，国内按永久收入花。代理：若 SWF 被用来补贴国内关联企业，平滑失败，且变成隐性产业政策，贸易课的补贴逻辑进来。稳定基金（短）与储蓄基金（长）应不同久期；混用会在油价跌时被迫在底卖出——与私人基金的赎回螺旋同构，对象是政治。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一只 1000 亿元的基金，按「每年最多花三年平均市值的 4%」的支出规则，一年只能花 40 亿；油价暴涨把基金推到 1500 亿，当年也只多花约 7 亿——支出规则把暴涨拦在国内吸收之外，这是「平滑」的可操作版本。")],-1)),(B(),l(i,null,{default:e(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOM%5B%22%E8%B5%84%E6%BA%90%E6%B6%A8%E4%BB%B7%EF%BC%8C%E5%A4%96%E6%B1%87%E6%B6%8C%E5%85%A5%22%5D%20--%3E%20Q%7B%22%E8%BF%99%E7%AC%94%E9%92%B1%E5%8E%BB%E5%93%AA%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E5%85%A8%E9%83%A8%E8%BF%9B%E5%9B%BD%E5%86%85%E6%94%AF%E5%87%BA%22%20--%3E%20RER%5B%22%E5%AE%9E%E9%99%85%E6%B1%87%E7%8E%87%E5%8D%87%E5%80%BC%22%5D%0A%20%20RER%20--%3E%20DD%5B%22%E5%8F%AF%E8%B4%B8%E6%98%93%E9%83%A8%E9%97%A8%E5%8F%97%E4%BC%A4%EF%BC%9A%E8%8D%B7%E5%85%B0%E7%97%85%22%5D%0A%20%20Q%20--%20%22%E5%85%88%E4%B9%B0%E6%B5%B7%E5%A4%96%E8%B5%84%E4%BA%A7%22%20--%3E%20SWF%5B%22SWF%20%E6%8C%81%E6%9C%89%E6%B5%B7%E5%A4%96%E7%BB%84%E5%90%88%22%5D%0A%20%20SWF%20--%3E%20SPEND%5B%22%E5%9B%BD%E5%86%85%E6%8C%89%E6%94%AF%E5%87%BA%E8%A7%84%E5%88%99%E5%8F%AA%E8%8A%B1%E6%8A%95%E8%B5%84%E6%94%B6%E7%9B%8A%22%5D%0A%20%20SPEND%20--%3E%20OK%5B%22%E6%B1%87%E7%8E%87%E5%B9%B3%E7%A8%B3%EF%BC%8C%E5%88%B6%E9%80%A0%E4%B8%9A%E4%BF%9D%E4%BD%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p>干预：部分国家让 SWF 兼做汇率，分账失败，储蓄变成怕浮动的弹药。本课主张分家，不是经验上总是分家。</p><p><span class="marginnote">挪威政府养老基金是教科书分家与规则。许多资源国的基金更接近财政余账。不要用一只基金的治理外推全部。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某笔港口投资的安全含义。不写东道国 CFIUS 的法律条文。欧债下一课是没有独立货币的主权，与 SWF 的债权国视角不同。不要把 SWF 写成「国家资本主义必然有效」或必然无效；治理是变量。量化栏的主权债定价不在此重做。</p><p><span class="marginnote">常见误区：SWF 存在不等于「国家更会理财」。治理差时它可能变成给关联企业的补贴渠道，平滑功能反而失效——决定性变量是分账与支出规则，不是有没有这只基金。</span></p><p>后课默认：SWF 是官方永久收入与顺差的久期转换，应与干预储备分账。治理决定平滑还是政治钱包。上流的长期官方腿在此。欧元区危机下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>储备是保险流动性；SWF 是跨期储蓄。应分账。</li><li>资源国按永久收入把租金投资海外，减轻荷兰病。</li><li>治理失败把 SWF 变成产业政策或干预弹药。</li><li>官方上流可以与私人 Lucas 缺失并存。</li><li>出处：Truman；Aizenman；永久收入 / 资源诅咒传统；Santiago 原则。</li></ul>',8))])}const W=o(d,[["render",F]]);export{f as __pageData,W as default};
